declare(strict_types=1);

namespace AdobeCommerce\ProductReviewSummaryAttributes\Observer;

use Magento\Framework\Data\Form;
use Magento\Framework\Data\Form\Element\Fieldset;
use Magento\Framework\DataObject;
use Magento\Framework\Event\Observer;
use Magento\Framework\Event\ObserverInterface;
use Magento\Framework\Registry;
use AdobeCommerce\ProductReviewSummaryAttributes\Model\ReviewAttributeContract;

/**
 * Configures the review summary attributes edit page: adds a "generated by the system" notice and locks
 * "Values Required", since the attributes have no value on the product edit form.
 *
 * The attribute edit page (Stores > Attributes > Product) is built with Magento\Framework\Data\Form and
 * only exposes the edited attribute through the registry.
 */
class ConfigureReviewAttributeEditForm implements ObserverInterface
{
    private const NOTICE_FIELD_ID = 'product_review_summary_notice';
    private const IS_REQUIRED_FIELD_ID = 'is_required';

    /**
     * @param Registry $registry
     * @param ReviewAttributeContract $contract
     */
    public function __construct(
        private readonly Registry $registry,
        private readonly ReviewAttributeContract $contract
    ) {
    }

    /**
     * Add the notice on top of the attribute properties fieldset and lock "Values Required".
     *
     * @param Observer $observer
     * @return void
     */
    public function execute(Observer $observer): void
    {
        $attribute = $this->registry->registry('entity_attribute');
        if (!$attribute instanceof DataObject || !$this->contract->isReviewSummaryAttribute($attribute)) {
            return;
        }

        $form = $observer->getEvent()->getData('form');
        $fieldset = $form instanceof Form ? $form->getElement('base_fieldset') : null;
        if (!$fieldset instanceof Fieldset) {
            return;
        }

        $fieldset->addField(
            self::NOTICE_FIELD_ID,
            'note',
            [
                'text' => '<div class="message message-notice">'
                    . __(
                        'This attribute is generated by the system from product reviews. '
                        . 'Its value is read-only and is not shown on the product edit form.'
                    )
                    . '</div>',
            ],
            '^'
        );

        $isRequired = $form->getElement(self::IS_REQUIRED_FIELD_ID);
        if ($isRequired !== null) {
            $isRequired->setDisabled(true);
        }
    }
}
